INSERT INTO series (id, name, userId) VALUES ('sr_saison1', 'Saison 1', 'ibaVT5FhANHbVkMp1Jj4bhQpkd1U7d8s');
INSERT INTO topics (id, name) VALUES ('tp_liberte', 'Liberté');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_54c937c4', 'L''esclave qui n''est pas capable d''assumer sa révolte ne mérite pas que l''on s''apitoie sur son sort. Seule la lutte libère.', 'Thomas Sankara', 'Burkinabé', 'Wikiquote FR — ''L''émancipation des femmes et la lutte de libération de l''Afrique'', Pathfinder Press, 2001, p. 46', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_c782053c', 'Lorsque le peuple se met debout, l''impérialisme tremble.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net — cité dans ''Figures de la révolution africaine'', Saïd Bouamama, La Découverte, 2017, p. 277', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_6d3c5fee', 'Pour être libre, il ne suffit pas de briser ses chaînes, il faut vivre d''une façon qui respecte et renforce la liberté des autres.', 'Nelson Mandela', 'Sud-Africain', '''Long Walk to Freedom'', Little Brown, 1995 — Nelson Mandela Foundation', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_e7998146', 'On naît libre et partout l''homme est dans les fers.', 'Jean-Jacques Rousseau', 'Suisse/Français', '''Du Contrat social'', Livre I, Chapitre 1, 1762', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_7e9398ba', 'L''homme est condamné à être libre.', 'Jean-Paul Sartre', 'Français', '''L''existentialisme est un humanisme'', Nagel, 1945', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_66cc2dc0', 'La liberté n''est jamais accordée volontairement par l''oppresseur ; elle doit être arrachée par l''opprimé.', 'Martin Luther King', 'Américain', '''Letter from Birmingham Jail'', 16 avril 1963 — The King Center, Atlanta', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_ee7f333b', 'Celui qui renonce à la liberté pour la sécurité ne mérite ni l''une ni l''autre.', 'Benjamin Franklin', 'Américain', 'Lettre à l''Assemblée de Pennsylvanie, novembre 1755', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_d28a9435', 'La vraie liberté intérieure — personne ne peut te l''ôter.', 'Épictète', 'Grec/Phrygien', '''Manuel'' (Enchiridion), §1, ~135 ap. J.-C.', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_73b54ff5', 'Ce n''est pas parce que les choses sont difficiles que nous n''osons pas ; c''est parce que nous n''osons pas qu''elles sont difficiles.', 'Sénèque', 'Romain', '''Lettres à Lucilius'', Lettre CIV', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_c621f7fe', 'La servitude volontaire est la plus vile de toutes les servitudes.', 'Étienne de La Boétie', 'Français', '''Discours de la servitude volontaire'', ~1548', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_04baebff', 'La liberté de la femme est la condition sine qua non de la liberté de tout le peuple.', 'Thomas Sankara', 'Burkinabé', 'Discours du 8 mars 1987 — thomassankara.net | Wikiquote FR', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_6016f366', 'Libérez vos esprits de l''esclavage mental, car seuls nous pouvons libérer nos esprits.', 'Bob Marley', 'Jamaïcain', '''Redemption Song'', album ''Uprising'', Island Records, 1980', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_171d82e8', 'Je ne suis pas libre si une sœur est enchaînée, même si ses chaînes sont très différentes des miennes.', 'Audre Lorde', 'Américaine', '''The Master''s Tools Will Never Dismantle the Master''s House'', 1984 — ''Sister Outsider'', Crossing Press', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_8ac8c920', 'La lutte est ma vie. Je vais continuer à lutter pour la liberté jusqu''à la fin de mes jours.', 'Nelson Mandela', 'Sud-Africain', 'Déclaration de Johannesburg, 26 juin 1961 — Nelson Mandela Foundation', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_39c71c7f', 'Sans lutte, il n''y a pas de progrès.', 'Frederick Douglass', 'Américain', 'Discours ''West India Emancipation'', 4 août 1857', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_3e191caa', 'Si les hommes naissaient libres, ils ne formeraient aucun concept du bien et du mal tant qu''ils demeureraient libres.', 'Baruch Spinoza', 'Néerlandais', '''Éthique'', Partie IV, Proposition LXVIII, 1677', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_4b0ea7aa', 'Ni le Coran ni la Bible n''ont jamais pu réconcilier le riche et le pauvre.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net — Babelio — Discours archivés', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_34b924e3', 'La liberté est absolument nécessaire pour le progrès des sciences et des arts libéraux.', 'Baruch Spinoza', 'Néerlandais', '''Traité théologico-politique'', Chapitre XX, 1670', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_7cde0f4e', 'Agis seulement d''après la maxime qui fait que tu peux vouloir en même temps qu''elle devienne une loi universelle.', 'Emmanuel Kant', 'Allemand', '''Fondements de la métaphysique des mœurs'', Section II, 1785', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_5d9971b6', 'L''obéissance à la loi qu''on s''est prescrite à soi-même est liberté.', 'Jean-Jacques Rousseau', 'Suisse/Français', '''Du Contrat social'', Livre I, Chapitre 8, 1762', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_dfc10cc1', 'La béatitude n''est pas la récompense de la vertu, mais la vertu elle-même.', 'Baruch Spinoza', 'Néerlandais', '''Éthique'', Partie V, Proposition XLII, 1677', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_3a68b233', 'La paix n''est pas l''absence de guerre; c''est une vertu, un état d''esprit, une disposition à la bienveillance, à la confiance, à la justice.', 'Baruch Spinoza', 'Néerlandais', '''Traité politique'', Chapitre V, §4, 1677', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_3214b52b', 'Tout ce qui est excellent est aussi difficile que rare.', 'Baruch Spinoza', 'Néerlandais', '''Éthique'', Partie V, Proposition XLII, Scolie, 1677', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_4c07ba44', 'La liberté est la reconnaissance de la nécessité.', 'Georg Wilhelm Friedrich Hegel', 'Allemand', '''Encyclopédie des sciences philosophiques'', §158, 1817', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_82325563', 'Chacun peut penser ce qui lui plaît et dire ce qu''il pense.', 'Baruch Spinoza', 'Néerlandais', '''Traité théologico-politique'', Chapitre XX, 1670', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_2201e92b', 'Nul ne peut désirer être heureux, bien agir et bien vivre sans désirer en même temps être, agir et vivre.', 'Baruch Spinoza', 'Néerlandais', '''Éthique'', Partie IV, Proposition XXI, 1677', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_9144f71a', 'Le Tao ne fait rien, et pourtant tout se fait par lui.', 'Lao Tzu', 'Chinois', '''Tao Te Ching'', Chapitre 37, ~VIe siècle av. J.-C.', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_27a7b9aa', 'Il n''est point de coexistence à venir qui ne soit fondée sur la rupture avec l''ordre colonialiste.', 'Aimé Césaire', 'Martiniquais', '''Discours sur le colonialisme'', Présence Africaine, 1955, p. 11', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_060be92e', 'Nous préférons un gouvernement africain dangereux à une administration étrangère irréprochable.', 'Kwame Nkrumah', 'Ghanéen', 'Discours d''indépendance du Ghana, 6 mars 1957 — Archives du Ghana', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_1ebc561b', 'L''esclave de l''amour est le seul vraiment libre.', 'Platon', 'Grec', '''Phèdre'', 252a, ~370 av. J.-C.', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_a63b62f5', 'La patrie ou la mort, nous vaincrons.', 'Thomas Sankara', 'Burkinabé', 'Cri de ralliement officiel de la révolution burkinabé, 1983-1987 — thomassankara.net', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_369c102c', 'Je m''efforce non de rire des actions humaines, non de les déplorer, non de les détester, mais de les comprendre.', 'Baruch Spinoza', 'Néerlandais', '''Traité politique'', Chapitre I, §4, 1677 (posthume)', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_2fd407ff', 'L''activité la plus élevée que l''homme puisse atteindre est l''apprentissage pour la compréhension, car comprendre c''est être libre.', 'Baruch Spinoza', 'Néerlandais', '''Traité de la réforme de l''entendement'', §1, 1677', 'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_55ad74d0', 'Un peuple conscient ne saurait confier la défense de sa patrie à un groupe d''hommes, quelles que soient leurs compétences.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net — Wikiquote FR', 'verified', 'tp_liberte');
INSERT INTO topics (id, name) VALUES ('tp_justice_et_egalite', 'Justice & Égalité');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_80a75811', 'L''injustice n''importe où est une menace pour la justice partout.', 'Martin Luther King', 'Américain', '''Letter from Birmingham Jail'', 16 avril 1963 — The King Center, Atlanta', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_c9ee8d0f', 'Il faut choisir entre le champagne pour quelques-uns et l''eau potable pour tous.', 'Thomas Sankara', 'Burkinabé', 'Le Monde, 23 décembre 2021 — thomassankara.net', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_39c99f12', 'Nul n''est né haïssant une autre personne à cause de la couleur de sa peau, de son origine ou de sa religion.', 'Nelson Mandela', 'Sud-Africain', '''Long Walk to Freedom'', Little Brown, 1995, p. 622 — Nelson Mandela Foundation', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_198c4cdf', 'La justice sans force est impuissante, la force sans justice est tyrannique.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 298, 1670 (posthume)', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_e2758f82', 'La négation de l''histoire et des réalisations intellectuelles des peuples africains noirs est le meurtre culturel.', 'Cheikh Anta Diop', 'Sénégalais', '''Civilisation ou Barbarie'', Présence Africaine, Paris, 1981, p. 10', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_57ac0e64', 'La décolonisation n''est jamais un phénomène naturel, c''est une violence.', 'Frantz Fanon', 'Martiniquais', '''Les Damnés de la Terre'', Maspero, 1961, p. 5', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_d89b3cc7', 'La justice est la première vertu des institutions sociales.', 'John Rawls', 'Américain', '''A Theory of Justice'', Harvard University Press, 1971, p. 3', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_7c2befba', 'La résistance à l''oppression est le plus sacré des droits.', 'Maximilien Robespierre', 'Français', 'Projet de Déclaration des droits de l''homme, Convention Nationale, 1793', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_e7333f2c', 'Lorsque les riches se font la guerre, ce sont les pauvres qui meurent.', 'Jean-Paul Sartre', 'Français', '''Le Diable et le Bon Dieu'', Gallimard, 1951', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_8515d6a6', 'L''inégalité ne peut être supprimée que par l''établissement d''une nouvelle société où hommes et femmes jouiront de droits égaux.', 'Thomas Sankara', 'Burkinabé', 'Discours du 8 mars 1987 — thomassankara.net | nofi.media', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_03bdf41a', 'Formez-vous, armez-vous de sciences jusqu''aux dents et arrachez votre patrimoine culturel.', 'Cheikh Anta Diop', 'Sénégalais', 'IFAN Université Cheikh Anta Diop, Dakar — Discours à la jeunesse africaine', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_74b50735', 'Nous devons préférer un pas avec le peuple plutôt que de faire dix pas sans lui.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net — Babelio', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_fcd84df3', 'Sans formation politique et idéologique, un militaire n''est qu''un criminel en puissance.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net — Wikiquote FR', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b10d4430', 'La connaissance du mal est une connaissance inadéquate.', 'Baruch Spinoza', 'Néerlandais', '''Éthique'', Partie IV, Proposition LXIV, 1677', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_63a4ac6a', 'Traite l''humanité, que ce soit dans ta propre personne ou celle d''autrui, toujours comme une fin, jamais seulement comme un moyen.', 'Emmanuel Kant', 'Allemand', '''Fondements de la métaphysique des mœurs'', Section II, 1785', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_0a717348', 'Ce qui n''est pas juste ne doit pas être appelé loi.', 'Saint Augustin', 'Berbère/Numide (Algérien)', '''De libero arbitrio'', Livre I, Chapitre 5, ~395', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_eb390d88', 'La justice est la vertu grâce à laquelle chacun possède ce qui lui appartient selon la loi.', 'Aristote', 'Grec', '''Éthique à Nicomaque'', Livre V, Chapitre 1 (1129b), ~335 av. J.-C.', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_667d4811', 'Ce n''est pas parce qu''une chose est juste qu''elle est légale, mais parce qu''elle est légale qu''elle est juste.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 312, 1670 (posthume)', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_932d53d3', 'Là où il n''y a pas de loi, il n''y a pas de liberté.', 'John Locke', 'Britannique', '''Second traité du gouvernement civil'', §57, 1689', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b8599c38', 'Ainsi l''impérialisme, tel le chasseur de la préhistoire, tue d''abord spirituellement et culturellement l''être avant de l''éliminer physiquement.', 'Cheikh Anta Diop', 'Sénégalais', '''Alerte sous les tropiques'', Présence Africaine, 2006', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_17f70857', 'L''égalité naturelle de tous les hommes est un principe fondamental de la morale.', 'David Hume', 'Écossais', '''Enquête sur les principes de la morale'', Section III, 1751', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_14ea3876', 'Si l''injustice est assez légère pour ne pas affecter les rouages de la machine, alors elle aussi fera partie des rouages.', 'Henry David Thoreau', 'Américain', '''La Désobéissance civile'', 1849', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_a29029d8', 'L''État qui n''est pas fondé sur la justice n''est qu''une grande organisation de brigands.', 'Saint Augustin', 'Berbère/Numide (Algérien)', '''La Cité de Dieu'', Livre IV, Chapitre 4, ~413-426', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_8576d396', 'Une action a une valeur morale non pas parce qu''elle produit les effets souhaités, mais parce qu''elle est accomplie par devoir.', 'Emmanuel Kant', 'Allemand', '''Fondements de la métaphysique des mœurs'', Section I, 1785', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_e0b4c5ed', 'Il est dangereux d''avoir raison dans des choses où les autorités établies ont tort.', 'Voltaire', 'Français', '''Catalogue des écrivains français'', 1752', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_870e2270', 'Je me suis battu contre la domination blanche et contre la domination noire.', 'Nelson Mandela', 'Sud-Africain', 'Discours au Rivonia Trial, 20 avril 1964 — Nelson Mandela Foundation', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_08e38d6c', 'La tyrannie d''un prince ne met pas un État si près de sa ruine que l''indifférence pour le bien public.', 'Montesquieu', 'Français', '''De l''esprit des lois'', Livre III, Chapitre 3, 1748', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_054249ed', 'L''homme libre ne pense à rien de moins qu''à la mort, et sa sagesse est une méditation non de la mort mais de la vie.', 'Baruch Spinoza', 'Néerlandais', '''Éthique'', Partie IV, Proposition LXVII, 1677', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_8ba962bf', 'Un homme vertueux voudra pour les autres les mêmes biens qu''il désire pour lui-même.', 'Baruch Spinoza', 'Néerlandais', '''Éthique'', Partie IV, Proposition XXXVII, 1677', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_85e2c529', 'Le droit est l''ensemble des conditions dans lesquelles la liberté des uns peut coexister avec la liberté des autres selon une loi universelle.', 'Emmanuel Kant', 'Allemand', '''Doctrine du droit'', Métaphysique des mœurs, §B, 1797', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_43ce4c8e', 'Ceux qui ont conduit des révolutions à moitié ne font que se creuser un tombeau.', 'Louis Antoine de Saint-Just', 'Français', 'Discours à la Convention Nationale, 1793', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_a6a152bb', 'L''égalité des droits des femmes est une nécessité fondamentale pour le triomphe de la révolution.', 'Thomas Sankara', 'Burkinabé', '''L''émancipation des femmes et la lutte de libération de l''Afrique'', Pathfinder Press, 2001', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_5ad18b50', 'Le bon sens est la chose du monde la mieux partagée.', 'René Descartes', 'Français', '''Discours de la méthode'', Première partie, 1637', 'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_708d419e', 'Pour examiner la vérité, il est besoin une fois dans sa vie de mettre toutes choses en doute autant qu''il se peut.', 'René Descartes', 'Français', '''Principes de la philosophie'', Partie I, §1, 1644', 'verified', 'tp_justice_et_egalite');
INSERT INTO topics (id, name) VALUES ('tp_courage_et_resilience', 'Courage & Résilience');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_ae194b89', 'Ne me jugez pas selon mes succès, jugez-moi sur le nombre de fois où je suis tombé et me suis relevé.', 'Nelson Mandela', 'Sud-Africain', '''Nelson Mandela By Himself'', Nelson Mandela Foundation, 2010', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b38fa4f7', 'Le courage, c''est non pas l''absence de peur, mais le triomphe sur elle.', 'Nelson Mandela', 'Sud-Africain', '''Long Walk to Freedom'', Little Brown, 1995 — Nelson Mandela Foundation', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_6c4fc291', 'Ce qui ne me tue pas me rend plus fort.', 'Friedrich Nietzsche', 'Allemand', '''Götzen-Dämmerung'' (Le Crépuscule des idoles), §8, 1888', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_ea90a646', 'Je me suis fait une raison. Soit je finirai vieil homme quelque part, soit ce sera une fin violente. Une fois qu''on l''a accepté, ce n''est plus qu''une question de temps.', 'Thomas Sankara', 'Burkinabé', 'Babelio — ''Thomas Sankara parle'' | thomassankara.net', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_3bf2e765', 'On peut tuer un homme mais pas ses idées.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net — Discours et interviews', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_dad4e84d', 'La Révolution démocratique et populaire a besoin d''un peuple de convaincus et non d''un peuple de vaincus.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net — Babelio', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_93e7c626', 'Les révolutionnaires n''ont pas peur de leurs fautes. Ils ont le courage politique de les reconnaître publiquement.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net — Discours officiels', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_71b5f9af', 'Après avoir gravi une grande colline, on découvre seulement qu''il y a encore beaucoup de collines à gravir.', 'Nelson Mandela', 'Sud-Africain', '''Long Walk to Freedom'', Conclusion, 1995', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_1553921e', 'La mort est quelque chose d''inévitable. Quand un homme a fait ce qu''il considère être son devoir, il peut reposer en paix.', 'Nelson Mandela', 'Sud-Africain', 'Documentaire ''Mandela'', 1994 — Nelson Mandela Foundation', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_0de0573e', 'Il vaut mieux périr que de haïr et craindre, et deux fois mieux, périr que de se faire haïr et craindre.', 'Friedrich Nietzsche', 'Allemand', '''Aurore'', §437, 1881', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_33a31512', 'Ce qui est fait par amour est toujours au-delà du bien et du mal.', 'Friedrich Nietzsche', 'Allemand', '''Par-delà bien et mal'' (Jenseits von Gut und Böse), §153, 1886', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_cae1ea0f', 'Si vous vous concentrez sur ce qui vous retient, vous ne pourrez jamais aller de l''avant.', 'Nelson Mandela', 'Sud-Africain', 'Conversation avec Richard Stengel, 3 mai 1993 — Nelson Mandela Foundation', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_cafa74be', 'Deviens ce que tu es.', 'Friedrich Nietzsche', 'Allemand', '''Ainsi parlait Zarathoustra'', Prologue, 1883-1885', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_831e03d6', 'Si vous voulez faire une œuvre durable, soyez patients, soyez bons, soyez humains.', 'Amadou Hampâté Bâ', 'Malien', '''Sur les traces d''Amkoullel l''enfant peul'', Actes Sud, 1991', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_75e4f0f0', 'Seule une jeunesse mobilisée, organisée, est dangereuse — elle effraye même les bombes atomiques.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net — Babelio', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_2d1e57a0', 'Ce qui est grand dans l''homme, c''est qu''il est un pont et non un but.', 'Friedrich Nietzsche', 'Allemand', '''Ainsi parlait Zarathoustra'', Prologue §4, 1883', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_a5c5cbf4', 'Nul ne peut longtemps porter un masque.', 'Sénèque', 'Romain', '''Lettres à Lucilius'', Lettre XXVI, ~65 ap. J.-C.', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b902be77', 'Connais l''ennemi et connais-toi toi-même; en cent batailles tu ne seras jamais vaincu.', 'Sun Tzu', 'Chinois', '''L''Art de la guerre'', Chapitre III, ~500 av. J.-C.', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_249d8b72', 'L''eau prend la forme du récipient qui la contient; le stratège prend la forme de l''ennemi qu''il affronte.', 'Sun Tzu', 'Chinois', '''L''Art de la guerre'', Chapitre VI, ~500 av. J.-C.', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_38e59e5f', 'Ne demande pas que les choses arrivent comme tu le veux, mais désire que les choses arrivent comme elles arrivent et tu seras serein.', 'Épictète', 'Grec/Phrygien', '''Manuel'' (Enchiridion), §8, ~135 ap. J.-C.', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_6bcfd1ed', 'Les obstacles à l''action favorisent l''action. Ce qui se dresse en travers du chemin devient le chemin.', 'Marc Aurèle', 'Romain', '''Pensées pour moi-même'', Livre V, §20, ~170 ap. J.-C.', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_1a609a84', 'Les grandes choses ne se font pas par impulsion, mais par une série de petites choses rassemblées.', 'Vincent van Gogh', 'Néerlandais', 'Lettre à son frère Théo van Gogh, 22 octobre 1882', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_50ff504f', 'La grandeur d''un homme se mesure à ce qu''il peut supporter.', 'Friedrich Nietzsche', 'Allemand', '''Ecce Homo'', ''Pourquoi je suis si sage'', §3, 1888', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_c0655982', 'Si tu te connais toi-même et connais ton ennemi, tu n''auras pas peur du résultat de cent batailles.', 'Sun Tzu', 'Chinois', '''L''Art de la guerre'', Chapitre III, ~500 av. J.-C.', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_a7f8729f', 'Magna ingenia latent. Les grands génies demeurent cachés.', 'Sénèque', 'Romain', '''Lettres à Lucilius'', Lettre LXXIX, ~65 ap. J.-C.', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_e0d7ba96', 'Le tigre ne proclame pas sa tigritude. Il bondit sur sa proie et la dévore.', 'Wole Soyinka', 'Nigérian', 'Débat à la Conférence de Berlin, 1964', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_c6acca87', 'Ce n''est pas parce que c''est difficile que nous ne le faisons pas. C''est parce que nous ne le faisons pas que c''est difficile.', 'Sénèque', 'Romain', '''Lettres à Lucilius'', Lettre CIV', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_563ec303', 'Sapere aude. Aie le courage de te servir de ton propre entendement.', 'Emmanuel Kant', 'Allemand', '''Réponse à la question: Qu''est-ce que les Lumières?'', 1784', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_339c4f18', 'Seul celui qui tente le possible sait ce qui lui est impossible.', 'René Char', 'Français', '''Feuillets d''Hypnos'', Gallimard, 1946', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_2cacd4a5', 'Les pensées sans contenu sont vides, les intuitions sans concepts sont aveugles.', 'Emmanuel Kant', 'Allemand', '''Critique de la raison pure'', Analytique transcendantale, §1, 1781', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_0fd3ee62', 'La vérité est le tout.', 'Georg Wilhelm Friedrich Hegel', 'Allemand', '''Phénoménologie de l''Esprit'', Préface, 1807', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_1d00ae0c', 'Tous les hommes désirent naturellement savoir.', 'Aristote', 'Grec', '''Métaphysique'', Livre I, §1 (980a21), ~335 av. J.-C.', 'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_1077a1f2', 'La raison est et ne doit être que l''esclave des passions.', 'David Hume', 'Écossais', '''Traité de la nature humaine'', Livre II, Partie III, Section III, 1739', 'verified', 'tp_courage_et_resilience');
INSERT INTO topics (id, name) VALUES ('tp_connaissance_et_sagesse', 'Connaissance & Sagesse');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_54ddc7a5', 'En Afrique, quand un vieillard meurt, c''est une bibliothèque qui brûle.', 'Amadou Hampâté Bâ', 'Malien', 'Discours à l''UNESCO, Paris, 1960 — Wikiquote FR | Dicocitations', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_a5ff3f04', 'L''éducation est l''arme la plus puissante que vous puissiez utiliser pour changer le monde.', 'Nelson Mandela', 'Sud-Africain', 'Discours au lancement de Mindset Network, 16 juillet 2003 — Nelson Mandela Foundation', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_681ae828', 'La facilité avec laquelle nous renonçons à notre culture ne s''explique que par notre ignorance de celle-ci.', 'Cheikh Anta Diop', 'Sénégalais', 'IFAN Dakar — ''Nations nègres et culture'', Présence Africaine, 1954', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_86811548', 'La sagesse commence dans l''émerveillement.', 'Socrate', 'Grec', 'Rapporté par Platon dans ''Théétète'', 155d, ~369 av. J.-C.', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_73e9c255', 'Le seul vrai savoir est de savoir que l''on ne sait rien.', 'Socrate', 'Grec', 'Rapporté par Platon dans ''Apologie de Socrate'', 21d, ~399 av. J.-C.', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_f4a8acd6', 'Connais-toi toi-même.', 'Socrate', 'Grec', 'Oracle de Delphes — rapporté par Platon dans ''Alcibiade I'', 124a', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_1fa737a0', 'Apprendre sans réfléchir est vain, réfléchir sans apprendre est dangereux.', 'Confucius', 'Chinois', '''Entretiens'' (Analectes), Livre II, §15 — traduction D.C. Lau, Penguin, 1979', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_4f75d936', 'Savoir ce que l''on sait et savoir ce que l''on ne sait pas : voilà la vraie science.', 'Confucius', 'Chinois', '''Entretiens'' (Analectes), Livre II, §17 — traduction D.C. Lau, Penguin, 1979', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_99e3250b', 'Ne fais pas à autrui ce que tu ne veux pas qu''on te fasse.', 'Confucius', 'Chinois', '''Entretiens'' (Analectes), Livre XII, §2 et Livre XV, §23 — traduction D.C. Lau', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_8f8dddc3', 'Si tu penses comme moi, tu es mon frère. Si tu ne penses pas comme moi, tu es deux fois mon frère, car tu m''ouvres un autre monde.', 'Amadou Hampâté Bâ', 'Malien', '''Amkoullel, l''enfant peul'', Actes Sud, 1991', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_ec8c94a3', 'La beauté d''un tapis vient de la variété de ses couleurs.', 'Amadou Hampâté Bâ', 'Malien', '''Aspects de la civilisation africaine'', Présence Africaine, 1972, p. 34', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_0d4502a8', 'La tradition transmise oralement est si précise que l''on peut reconstituer les grands événements des siècles passés.', 'Amadou Hampâté Bâ', 'Malien', '''Aspects de la civilisation africaine'', Présence Africaine, 1972, p. 25', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_2aaa2eef', 'La coutume est la grande directrice de la vie humaine.', 'David Hume', 'Écossais', '''Enquête sur l''entendement humain'', Section V, 1748', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_d2d6e718', 'Les Africains doivent bâtir des humanités à base d''égyptien ancien, comme l''Occident l''a fait à partir de la base gréco-latine.', 'Cheikh Anta Diop', 'Sénégalais', '''Nations nègres et culture'', Présence Africaine, 1954', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_882d1f3c', 'Nous aspirons tous au triomphe de la notion d''espèce humaine, de sorte que l''histoire particulière de chaque race s''efface devant celle de l''homme.', 'Cheikh Anta Diop', 'Sénégalais', '''Nations nègres et culture'', Présence Africaine, 1954', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_a07cef20', 'L''Afrique doit opter pour une politique de développement scientifique ; sa vulnérabilité est la conséquence d''une déficience technique.', 'Cheikh Anta Diop', 'Sénégalais', 'IFAN Dakar — ''Les fondements économiques et culturels d''un État fédéral d''Afrique noire'', Présence Africaine', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_15dd079c', 'La connaissance sans conscience n''est que ruine de l''âme.', 'François Rabelais', 'Français', '''Pantagruel'', Livre II, Chapitre 8, 1532', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_ba03441a', 'La raison est la lumière naturelle de l''homme.', 'René Descartes', 'Français', '''Règles pour la direction de l''esprit'', Règle I, 1628 (posthume)', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_2f0226a3', 'Philosopher, c''est apprendre à mourir.', 'Michel de Montaigne', 'Français', '''Essais'', Livre I, Chapitre 20, 1580', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_db4fc5b9', 'L''ignorance engendre plus de confiance que ne le fait la connaissance.', 'Charles Darwin', 'Britannique', '''The Descent of Man'', John Murray, 1871, Introduction', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_99b7de08', 'L''abandon de nos langues nous couperait de nos traditions et modifierait la structure même de notre esprit.', 'Amadou Hampâté Bâ', 'Malien', '''Aspects de la civilisation africaine'', Présence Africaine, 1972, p. 32', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_d6cec6bc', 'En tradition africaine, la parole est sacrée car elle engage l''être total.', 'Amadou Hampâté Bâ', 'Malien', '''Aspects de la civilisation africaine'', Présence Africaine, 1972', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_20b9c4dc', 'La raison est l''esclave et ne peut prétendre à aucun autre emploi que de servir et d''obéir.', 'David Hume', 'Écossais', '''Traité de la nature humaine'', Livre II, Partie III, §3, 1739', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_784d8ec6', 'Le bonheur de ta vie dépend de la qualité de tes pensées.', 'Marc Aurèle', 'Romain', '''Pensées pour moi-même'' (Meditations), Livre III, §9 — traduction Gregory Hays', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_d4bff03d', 'Vous avez le pouvoir sur votre esprit, pas sur les événements extérieurs. Réalisez cela, et vous trouverez la force.', 'Marc Aurèle', 'Romain', '''Pensées pour moi-même'' (Meditations), Livre IV, §3 — traduction Gregory Hays', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_393faf17', 'Si tu es en souffrance à cause d''une chose extérieure, ce n''est pas elle qui te blesse, mais le jugement que tu portes sur elle.', 'Marc Aurèle', 'Romain', '''Pensées pour moi-même'' (Meditations), Livre VIII, §45', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_535aa823', 'La raison et la foi ne s''opposent pas; ce qui est vrai en philosophie ne peut être faux en théologie.', 'Ibn Rushd (Averroès)', 'Andalou/Marocain', '''Discours décisif'' (Fasl al-maqal), ~1179', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_8b087f34', 'L''intellect humain est une faculté qui s''élève graduellement vers la connaissance universelle.', 'Ibn Sina (Avicenne)', 'Perse (Ouzbékistan)', '''Le Livre de la guérison'', Psychologie, §1, ~1020', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_0d2b4311', 'Que sais-je?', 'Michel de Montaigne', 'Français', '''Essais'', Livre II, Chapitre 12 (''Apologie de Raymond Sebond''), 1580', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_13e1da5c', 'La grandeur de l''homme est qu''il est un être de désir, d''illusions et d''espoir.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 148, 1670 (posthume)', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_0783fb65', 'Le cœur a ses raisons que la raison ne connaît point.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 277, 1670 (posthume)', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_6743098a', 'Tout notre raisonnement se réduit à céder au sentiment.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 274, 1670 (posthume)', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_5d4c41f0', 'Ce que l''on conçoit bien s''énonce clairement, et les mots pour le dire arrivent aisément.', 'Nicolas Boileau', 'Français', '''L''Art poétique'', Chant I, 1674', 'verified', 'tp_connaissance_et_sagesse');
INSERT INTO topics (id, name) VALUES ('tp_humanite_et_fraternite', 'Humanité & Fraternité');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_1ae12ac1', 'Ubuntu : Je suis parce que nous sommes.', 'Philosophie Ubuntu', 'Africain', 'Concept bantou ''umuntu ngumuntu ngabantu'' — diffusé internationalement par Desmond Tutu et Nelson Mandela', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_a8099db4', 'Notre liberté est incomplète sans la liberté des autres.', 'Nelson Mandela', 'Sud-Africain', 'Discours à la journée de solidarité avec la Palestine — Nelson Mandela Foundation', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_4f6a4c30', 'Nous devons vivre ensemble comme des frères, ou mourir ensemble comme des idiots.', 'Martin Luther King', 'Américain', 'Discours ''A Choice of Two Ways'', 1961 — The King Papers, Stanford University', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_53587993', 'A un interlocuteur qui me demandait ce que l''Afrique pourrait apporter, j''ai répondu : ''le rire, que vous avez perdu.''', 'Amadou Hampâté Bâ', 'Malien', '''Aspects de la civilisation africaine'', Présence Africaine, 1972, p. 21-22', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_270ce6da', 'En Afrique traditionnelle, l''individu est inséparable de sa lignée, qui continue de vivre à travers lui.', 'Amadou Hampâté Bâ', 'Malien', '''Amkoullel, l''enfant peul'', Actes Sud, 1991', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_4de8bbdd', 'L''homme est un être social par nature.', 'Aristote', 'Grec', '''Politique'', Livre I, §2 (''zoon politikon''), ~335 av. J.-C.', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_a13657b1', 'Nous sommes tous responsables de tous.', 'Fiodor Dostoïevski', 'Russe', '''Les Frères Karamazov'', 1880, discours du père Zosime', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_e873725a', 'Aucun homme n''est une île, entière en elle-même.', 'John Donne', 'Britannique', '''Devotions upon Emergent Occasions'', 1624, Méditation XVII', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_de7d6658', 'La tradition se préoccupe de la personne humaine en tant que multiplicité intérieure, appelée à s''ordonner et à s''unifier.', 'Amadou Hampâté Bâ', 'Malien', '''Aspects de la civilisation africaine'', Présence Africaine, 1972, p. 17', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_04b69b4c', 'Agis seulement d''après la maxime que tu peux vouloir être une loi universelle.', 'Emmanuel Kant', 'Allemand', '''Fondation de la métaphysique des mœurs'', 1785', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_ddca9dd0', 'Nous sommes tous liés par un destin commun sur cette petite planète.', 'John F. Kennedy', 'Américain', 'Discours à l''Université Américaine, 10 juin 1963', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_f1cf3b16', 'L''amitié véritable est l''autre soi-même.', 'Cicéron', 'Romain', '''Laelius de Amicitia'', §21, ~44 av. J.-C.', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_92728abd', 'La société humaine est l''expression de la nature sociale de l''homme.', 'Ibn Khaldoun', 'Tunisien', '''Al-Muqaddimah'', Chapitre II, §1, 1377', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_c3462f97', 'La compassion est la base de toute moralité.', 'Arthur Schopenhauer', 'Allemand', '''Le Fondement de la morale'', 1840', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_febe9784', 'Les contes sont le message d''hier, destiné à demain, transmis à travers aujourd''hui.', 'Amadou Hampâté Bâ', 'Malien', 'Presses Universitaires de Bordeaux | ''Il n''y a pas de petite querelle''', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_9cde7349', 'Nous estimons que la dette s''analyse d''abord de par son origine. Les origines de la dette remontent aux origines du colonialisme.', 'Thomas Sankara', 'Burkinabé', 'Discours à l''OUA, Addis-Abeba, juillet 1987 — thomassankara.net | Scribd', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b08dcbf7', 'La solidarité de groupe (''asabiyya) est le fondement de toute civilisation.', 'Ibn Khaldoun', 'Tunisien', '''Al-Muqaddimah'', Livre II, §8, 1377', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_ecced277', 'Une bonne tête et un bon cœur sont toujours une combinaison redoutable.', 'Nelson Mandela', 'Sud-Africain', '''Nelson Mandela By Himself'', Nelson Mandela Foundation, 2010', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_905afa50', 'L''être humain est social par nature; il lui est impossible de vivre seul.', 'Ibn Khaldoun', 'Tunisien', '''Al-Muqaddimah'', Livre I, §2, 1377', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_0adfc286', 'Homo sum : nihil humani a me alienum puto. Je suis homme, et rien d''humain ne m''est étranger.', 'Térence', 'Carthaginois/Romain', '''Héautontimorouménos'', Acte I, Scène 1, v. 77, 163 av. J.-C.', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_47397de6', 'L''amitié est une âme en deux corps.', 'Aristote', 'Grec', 'Rapporté par Diogène Laërce, ''Vies des philosophes'', Livre V', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_f0a732b2', 'L''âme sœur d''un être humain, c''est un autre être humain.', 'Sénèque', 'Romain', '''Lettres à Lucilius'', Lettre XLVIII, ~65 ap. J.-C.', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b25cb783', 'Le bonheur est la fin que se propose toute action humaine.', 'Aristote', 'Grec', '''Éthique à Nicomaque'', Livre I, Chapitre 7 (1097a), ~335 av. J.-C.', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_147a35f5', 'Nous sommes ce que nous faisons répétitivement. L''excellence n''est donc pas un acte mais une habitude.', 'Aristote', 'Grec', '''Éthique à Nicomaque'', Livre II, Chapitre 4 (1105b), ~335 av. J.-C.', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b669b06f', 'Le fanatisme est un monstre qui ose se dire fils de la religion.', 'Voltaire', 'Français', '''Traité sur la tolérance'', Chapitre I, 1763', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_fe042a90', 'La charité est la bienveillance universelle.', 'Gottfried Wilhelm Leibniz', 'Allemand', '''Nouveaux essais sur l''entendement humain'', Livre II, Chapitre 28, 1704', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_eb7025f5', 'Quand vous voyez un homme vertueux, efforcez-vous de l''imiter. Quand vous voyez un homme sans vertu, examinez votre propre caractère.', 'Confucius', 'Chinois', '''Entretiens'' (Analectes), Livre IV, §17, ~500 av. J.-C.', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_5f9fc0fb', 'L''examen de conscience doit précéder toute réconciliation avec autrui.', 'Confucius', 'Chinois', '''Entretiens'' (Analectes), Livre I, §4, ~500 av. J.-C.', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_2246431e', 'La chaleur humaine est supérieure à toute architecture.', 'Amadou Hampâté Bâ', 'Malien', '''Aspects de la civilisation africaine'', Présence Africaine, 1972, p. 23', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b657cb8d', 'Tous les hommes sont frères sous les rayons du même soleil.', 'Voltaire', 'Français', '''Traité sur la tolérance'', Chapitre XXII, 1763', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_ddcd38a4', 'La société est la continuation de la famille.', 'Auguste Comte', 'Français', '''Cours de philosophie positive'', Leçon 50, 1842', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_be182941', 'Personne n''est né haïssant une autre personne en raison de la couleur de sa peau.', 'Nelson Mandela', 'Sud-Africain', '''Long Walk to Freedom'', Little Brown, 1995, p. 622', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_4c6fdbbd', 'L''humanité se compose de plus de morts que de vivants.', 'Auguste Comte', 'Français', '''Politique positive'', Tome II, 1852', 'verified', 'tp_humanite_et_fraternite');
INSERT INTO topics (id, name) VALUES ('tp_pouvoir_et_politique', 'Pouvoir & Politique');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_e40a7543', 'Nous estimons que la dette s''analyse d''abord de par son origine. Les origines de la dette remontent aux origines du colonialisme.', 'Thomas Sankara', 'Burkinabé', 'Discours à l''OUA, Addis-Abeba, juillet 1987 — thomassankara.net | Scribd | Wikiquote', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_9eaaa10e', 'Le néocolonialisme est le dernier stade de l''impérialisme.', 'Kwame Nkrumah', 'Ghanéen', '''Neo-Colonialism: The Last Stage of Imperialism'', Nelson, 1965 — titre même du livre', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_badeceb8', 'Le peuple est le seul vrai souverain.', 'Jean-Jacques Rousseau', 'Suisse/Français', '''Du Contrat social'', Livre II, 1762', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b808327d', 'La démocratie est le gouvernement du peuple, par le peuple, pour le peuple.', 'Abraham Lincoln', 'Américain', 'Discours de Gettysburg, 19 novembre 1863', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_3d40f0c3', 'Le colonialisme n''est pas une machine à penser, n''est pas un corps doué de raison. Il est la violence à l''état nu.', 'Frantz Fanon', 'Martiniquais', '''Les Damnés de la Terre'', Maspero, 1961, p. 5', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_5b7fb840', 'Chaque génération doit découvrir sa mission, la remplir ou la trahir.', 'Frantz Fanon', 'Martiniquais', '''Les Damnés de la Terre'', Maspero, 1961, Conclusion', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_6d8ca804', 'Je me suis battu contre la domination blanche et contre la domination noire.', 'Nelson Mandela', 'Sud-Africain', 'Discours au Rivonia Trial, 20 avril 1964 — Nelson Mandela Foundation', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_f557489f', 'Le pouvoir corrompt, le pouvoir absolu corrompt absolument.', 'Lord Acton', 'Britannique', 'Lettre à Mandell Creighton, 5 avril 1887', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_54261c02', 'L''Afrique unie est la seule réponse au néocolonialisme.', 'Kwame Nkrumah', 'Ghanéen', '''Africa Must Unite'', Heinemann, 1963', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_07e5dd45', 'Ceux qui ont conduit des révolutions à moitié ne font que se creuser un tombeau.', 'Louis Antoine de Saint-Just', 'Français', 'Discours à la Convention Nationale, 1793', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_1737bdb8', 'L''unité africaine est la clé de la renaissance du continent.', 'Haile Selassie', 'Éthiopien', 'Discours fondateur de l''OUA, Addis-Abeba, 25 mai 1963', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_1d7fb5ce', 'La force ne crée pas le droit.', 'Jean-Jacques Rousseau', 'Suisse/Français', '''Du Contrat social'', Livre I, Chapitre 3, 1762', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_a414b6f1', 'Nous préférons un gouvernement africain dangereux à une administration étrangère irréprochable.', 'Kwame Nkrumah', 'Ghanéen', 'Discours d''indépendance du Ghana, 6 mars 1957', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_88b7ff16', 'Long speeches, the shaking of fists and strongly worded resolutions do not bring about mass action.', 'Nelson Mandela', 'Sud-Africain', 'Discours ''No Easy Walk to Freedom'', Transvaal ANC, 21 septembre 1953 — Nelson Mandela Foundation', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_99bef94c', 'Ceux qui veulent exploiter l''Afrique sont les mêmes qui exploitent l''Europe.', 'Thomas Sankara', 'Burkinabé', 'samabac.com — thomassankara.net', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_660bbc1b', 'Vivre en révolutionnaire, mourir en révolutionnaire.', 'Thomas Sankara', 'Burkinabé', 'samabac.com — thomassankara.net', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_1a6fd467', 'Il est plus sûr d''être craint qu''aimé, mais le mieux serait d''être les deux à la fois.', 'Machiavel', 'Italien', '''Le Prince'', Chapitre XVII, 1532', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_9aeba1c7', 'La fin justifie les moyens.', 'Machiavel', 'Italien', '''Le Prince'', Chapitre XVIII, 1532', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b5225a10', 'Quiconque veut fonder un État et lui donner des lois doit supposer les hommes méchants par nature.', 'Machiavel', 'Italien', '''Discours sur la première décade de Tite-Live'', Livre I, Chapitre 3, 1531', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_898657ab', 'L''accumulation du pouvoir législatif, exécutif et judiciaire dans les mêmes mains constitue la tyrannie.', 'John Locke', 'Britannique', '''Second traité du gouvernement civil'', §107, 1689', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_186fd20a', 'Pour qu''on ne puisse abuser du pouvoir, il faut que le pouvoir arrête le pouvoir.', 'Montesquieu', 'Français', '''De l''esprit des lois'', Livre XI, Chapitre 4, 1748', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_fd8371cf', 'Les lois inutiles affaiblissent les lois nécessaires.', 'Montesquieu', 'Français', '''De l''esprit des lois'', Livre XXIX, Chapitre 16, 1748', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_88468e5c', 'Les grandes dynasties naissent dans la rudesse et meurent dans le raffinement.', 'Ibn Khaldoun', 'Tunisien', '''Al-Muqaddimah'', Livre III, §1, 1377', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_de35244a', 'L''autorité politique naît de la solidarité de groupe et non du génie individuel.', 'Ibn Khaldoun', 'Tunisien', '''Al-Muqaddimah'', Livre II, Chapitre 17, 1377', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_6d9b1cab', 'La publicité est le critère de la légitimité d''une action politique.', 'Emmanuel Kant', 'Allemand', '''Vers la paix perpétuelle'', Supplément II, 1795', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_3f8d872f', 'La liberté politique ne consiste point à faire ce que l''on veut.', 'Montesquieu', 'Français', '''De l''esprit des lois'', Livre XI, Chapitre 3, 1748', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_3fcc4dcf', 'Ce n''est pas la conscience qui détermine la vie, mais la vie qui détermine la conscience.', 'Karl Marx', 'Allemand', '''Contribution à la critique de l''économie politique'', Préface, 1859', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_718cd8d5', 'Les philosophes n''ont fait qu''interpréter diversement le monde; il s''agit maintenant de le transformer.', 'Karl Marx', 'Allemand', '''Thèses sur Feuerbach'', Thèse XI, 1845', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_68fae7c6', 'L''histoire se répète deux fois : la première fois comme tragédie, la seconde comme farce.', 'Karl Marx', 'Allemand', '''Le 18 Brumaire de Louis-Napoléon Bonaparte'', Chapitre I, 1852', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_e3b6e6d6', 'La révolution n''est pas un dîner de gala.', 'Mao Zedong', 'Chinois', '''Rapport sur l''enquête dans le Hounan'', mars 1927', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_768a76c9', 'Donner de bonnes lois à un peuple vicieux, c''est donner un marteau à un fou.', 'Voltaire', 'Français', '''Questions sur l''Encyclopédie'', 1770', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_a66a5901', 'La politique est l''art du possible.', 'Otto von Bismarck', 'Allemand', 'Interview à Saint-Pétersbourg, 11 août 1867', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_2bb6467b', 'Le colonisé qui décide de réaliser ce programme est prêt à tout moment à la violence.', 'Frantz Fanon', 'Martiniquais', '''Les Damnés de la Terre'', Maspero, 1961, p. 6', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_d05164d7', 'Il faut d''abord oser pour ensuite pouvoir.', 'Georges Jacques Danton', 'Français', 'Discours à l''Assemblée Législative, 2 septembre 1792', 'verified', 'tp_pouvoir_et_politique');
INSERT INTO topics (id, name) VALUES ('tp_action_et_changement', 'Action & Changement');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_5d9bc07b', 'Nous nous mirons dans le monde. Si nous pouvions nous changer nous-mêmes, les tendances dans le monde changeront aussi.', 'Mahatma Gandhi', 'Indien', '''Indian Opinion'', 1913 — Collected Works of Mahatma Gandhi, Vol. 13, Chapitre 153. NOTE: La citation populaire ''Sois le changement...'' est une paraphrase non authentifiée de ce texte.', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_8f0eb83e', 'Un long voyage commence par un seul pas.', 'Lao Tzu', 'Chinois', '''Tao Te Ching'', Chapitre 64 — confirmé par Wikipedia, Taoism.net et multiple traductions académiques', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_6ddee554', 'Sans lutte, il n''y a pas de progrès.', 'Frederick Douglass', 'Américain', 'Discours ''West India Emancipation'', 4 août 1857 — Frederick Douglass Papers, Library of Congress', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b8777a2e', 'Si tu n''avances pas, tu recules.', 'Lao Tzu', 'Chinois', '''Tao Te Ching'', Chapitre 9, ~VIe siècle av. J.-C.', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_f1b76ce7', 'Chaque génération doit découvrir sa mission, la remplir ou la trahir.', 'Frantz Fanon', 'Martiniquais', '''Les Damnés de la Terre'', Maspero, 1961, Conclusion', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_7dc7ec1f', 'Gouverner un grand pays est comme faire cuire un petit poisson : surtout ne pas trop y toucher.', 'Lao Tzu', 'Chinois', '''Tao Te Ching'', Chapitre 60, ~VIe siècle av. J.-C.', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_42b38ce9', 'Le sage n''accumule pas : plus il aide les autres, plus il possède.', 'Lao Tzu', 'Chinois', '''Tao Te Ching'', Chapitre 81, ~VIe siècle av. J.-C.', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_74cd7b17', 'La révolution n''est pas un dîner de gala.', 'Mao Zedong', 'Chinois', '''Rapport sur l''enquête dans le Hounan'', mars 1927', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_bc950bf0', 'La lutte est ma vie. Je vais continuer à lutter pour la liberté jusqu''à la fin de mes jours.', 'Nelson Mandela', 'Sud-Africain', 'Déclaration de Johannesburg, 26 juin 1961 — Nelson Mandela Foundation', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_ab40baae', 'L''homme vertueux désire être lent dans ses paroles mais prompt dans ses actions.', 'Confucius', 'Chinois', '''Entretiens'' (Analectes), Livre IV, §24, ~500 av. J.-C.', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b61b7873', 'Les grandes choses ne se font pas par impulsion, mais par une série de petites choses rassemblées.', 'Vincent van Gogh', 'Néerlandais', 'Lettre à son frère Théo van Gogh, 22 octobre 1882 — Van Gogh Museum Archive', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_8f7e3fcc', 'La victoire suprême est de vaincre sans combattre.', 'Sun Tzu', 'Chinois', '''L''Art de la guerre'', Chapitre III, ~500 av. J.-C.', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_baef465a', 'La libération de la femme est une nécessité fondamentale pour le triomphe de la révolution.', 'Thomas Sankara', 'Burkinabé', 'Discours 8 mars 1987 — thomassankara.net', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_847f5def', 'Toute guerre est fondée sur la tromperie.', 'Sun Tzu', 'Chinois', '''L''Art de la guerre'', Chapitre I, ~500 av. J.-C.', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_53ac4a40', 'Il faut d''abord oser pour ensuite pouvoir.', 'Georges Jacques Danton', 'Français', 'Discours à l''Assemblée Législative, 2 septembre 1792', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_3f195dec', 'L''imagination est plus importante que le savoir.', 'Albert Einstein', 'Allemand/Américain', '''What Life Means to Einstein'', Saturday Evening Post, 26 octobre 1929', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_1e46ebab', 'Seul celui qui tente le possible sait ce qui lui est impossible.', 'René Char', 'Français', '''Feuillets d''Hypnos'', Gallimard, 1946', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_0d6bbba3', 'Vivre sans but défini, c''est vivre pour rien.', 'Marc Aurèle', 'Romain', '''Pensées pour moi-même'', Livre VI, §17, ~170 ap. J.-C.', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_bb992081', 'Le présent est ce qui se fait, non ce qui est fait.', 'Henri Bergson', 'Français', '''Matière et mémoire'', PUF, 1896, Chapitre IV', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_24533e10', 'Les États ont une durée de vie comme les individus : ils naissent, grandissent, vieillissent et meurent.', 'Ibn Khaldoun', 'Tunisien', '''Al-Muqaddimah'', Livre III, §12, 1377', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_5b830b59', 'Ce n''est pas la conscience qui détermine la vie, mais la vie qui détermine la conscience.', 'Karl Marx', 'Allemand', '''Contribution à la critique de l''économie politique'', Préface, 1859', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_234dc6a3', 'L''éducation fait la plus grande différence entre les hommes.', 'John Locke', 'Britannique', '''Quelques pensées sur l''éducation'', §1, 1693', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_85833329', 'La littérature est la conscience d''une nation.', 'Wole Soyinka', 'Nigérian', 'Discours Nobel de Littérature, Stockholm, 8 décembre 1986', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_2ed92e8e', 'Nous faisons la guerre pour vivre en paix.', 'Aristote', 'Grec', '''Éthique à Nicomaque'', Livre X, Chapitre 7 (1177b), ~335 av. J.-C.', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_a27961d2', 'L''état de nature est l''état de guerre de tous contre tous.', 'Thomas Hobbes', 'Britannique', '''Léviathan'', Partie I, Chapitre 13, 1651', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_2ce6a079', 'La vie de l''homme à l''état de nature est solitaire, misérable, dangereuse, animale et brève.', 'Thomas Hobbes', 'Britannique', '''Léviathan'', Partie I, Chapitre 13, 1651', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_78d934f0', 'Ceux qui ne peuvent se souvenir du passé sont condamnés à le répéter.', 'George Santayana', 'Espagnol/Américain', '''La Vie de la raison'', Vol. I, Chapitre XII, 1905', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_6e130813', 'Les révolutions ne se font pas avec des fleurs.', 'Lénine', 'Russe', '''Que faire?'', 1902', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_4d239529', 'Parler est d''argent, se taire est d''or.', 'Thomas Carlyle', 'Écossais', '''Sartor Resartus'', Livre III, Chapitre III, 1833-34', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_ed30f3d8', 'L''expérience est une lanterne que l''on porte sur le dos et qui n''éclaire que le chemin parcouru.', 'Confucius', 'Chinois', '''Entretiens'' (Analectes), Livre VII, §1, ~500 av. J.-C.', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_9fb1fb87', 'Commencer, c''est déjà à moitié faire.', 'Ausone', 'Romain/Gaulois', '''Epigrammata'', IV, ~400 ap. J.-C.', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_35ee89a5', 'Peu importe la lenteur de ta marche, tant que tu ne t''arrêtes pas.', 'Confucius', 'Chinois', '''Entretiens'' (Analectes), Livre IX, §23, ~500 av. J.-C.', 'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_21511e1d', 'Le temps ne respecte pas ce qui se fait sans lui.', 'Aimé Césaire', 'Martiniquais', '''Cahier d''un retour au pays natal'', Présence Africaine, 1939', 'verified', 'tp_action_et_changement');
INSERT INTO topics (id, name) VALUES ('tp_identite_et_culture', 'Identité & Culture');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_306e96f2', 'La négation de l''histoire africaine est le meurtre culturel de l''Afrique.', 'Cheikh Anta Diop', 'Sénégalais', '''Civilisation ou Barbarie'', Présence Africaine, Paris, 1981, p. 10', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_08be25f3', 'La tradition orale africaine est d''une rigueur que peu de civilisations écrites peuvent égaler.', 'Amadou Hampâté Bâ', 'Malien', '''Aspects de la civilisation africaine'', Présence Africaine, 1972, p. 25', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_ef001441', 'Le poison culturel inoculé dès la plus tendre enfance est devenu partie intégrante de notre substance.', 'Cheikh Anta Diop', 'Sénégalais', 'IFAN Dakar — Discours à la jeunesse africaine', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_f4d7ff61', 'Écrire dans sa langue maternelle est un acte politique de résistance.', 'Ngugi wa Thiong''o', 'Kenyan', '''Decolonising the Mind: The Politics of Language in African Literature'', James Currey, 1986', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_bcdb4e43', 'Qui contrôle l''histoire contrôle le présent.', 'George Orwell', 'Britannique', '''1984'', Secker & Warburg, 1949 — ''Celui qui contrôle le passé contrôle le futur''', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_a1ab7eb5', 'L''identité n''est pas donnée une fois pour toutes : elle se construit et se reconstruit.', 'Amin Maalouf', 'Libanais/Français', '''Les Identités meurtrières'', Grasset, 1998', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_c132c1e9', 'Le danger d''une histoire unique, c''est qu''elle vole la dignité des peuples.', 'Chimamanda Ngozi Adichie', 'Nigériane', 'TED Talk ''The Danger of a Single Story'', TEDGlobal, 2009', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_c912f554', 'La langue est la maison de l''être.', 'Martin Heidegger', 'Allemand', '''Lettre sur l''Humanisme'', 1947', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_94554ba2', 'Ce que nous sommes dépend de ce que nous avons été.', 'Wilhelm Dilthey', 'Allemand', '''Introduction aux sciences de l''esprit'', 1883', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_9610f277', 'La philosophie est son temps saisi dans la pensée.', 'Georg Wilhelm Friedrich Hegel', 'Allemand', '''Principes de la philosophie du droit'', Préface, 1820', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_17692430', 'L''identité narrative est cette identité que nous construisons en racontant notre propre histoire.', 'Paul Ricoeur', 'Français', '''Soi-même comme un autre'', Seuil, 1990, p. 174', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_e6dae24c', 'Raconter, c''est déjà expliquer.', 'Paul Ricoeur', 'Français', '''Temps et récit'', Tome I, Seuil, 1983', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_928883e8', 'L''Égypte ancienne est à l''Afrique noire ce que la Grèce et Rome sont à l''Occident.', 'Cheikh Anta Diop', 'Sénégalais', '''Nations nègres et culture'', Présence Africaine, 1954, p. 14', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_fcffe95d', 'Ce que l''on nomme le ''miracle grec'' est en réalité le miracle africain transmis à la Grèce.', 'Cheikh Anta Diop', 'Sénégalais', '''Civilisation ou Barbarie'', Présence Africaine, 1981, p. 251', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_4e2c43e3', 'L''imitation est suicide.', 'Ralph Waldo Emerson', 'Américain', '''Self-Reliance'', Essays: First Series, 1841', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_28cdd7c3', 'Ce que tu es parle si fort que je n''entends pas ce que tu dis.', 'Ralph Waldo Emerson', 'Américain', '''Letters and Social Aims'', 1876', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_2e52fd88', 'Chaque homme porte la forme entière de l''humaine condition.', 'Michel de Montaigne', 'Français', '''Essais'', Livre III, Chapitre 2, 1588', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_bf8dd843', 'Ma bouche sera la bouche des malheurs qui n''ont point de bouche, ma voix la liberté de celles qui s''affaissent au cachot du désespoir.', 'Aimé Césaire', 'Martiniquais', '''Cahier d''un retour au pays natal'', Présence Africaine, 1939', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_f982829c', 'L''Algérienne, en combattant pour la révolution, s''est aussi battue pour sa propre libération.', 'Frantz Fanon', 'Martiniquais', '''L''An V de la révolution algérienne'', Maspero, 1959, p. 38', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_569dd45c', 'Les langues africaines sont assez riches pour exprimer la pensée scientifique moderne.', 'Cheikh Anta Diop', 'Sénégalais', 'IFAN Dakar — Discours sur les langues africaines, 1977', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_8fae18ab', 'Formez-vous, armez-vous de sciences jusqu''aux dents, et arrachez votre patrimoine culturel.', 'Cheikh Anta Diop', 'Sénégalais', 'IFAN Université Cheikh Anta Diop — Discours à la jeunesse africaine, Dakar', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_597e816b', 'L''Egypte est nègre dans ses origines.', 'Cheikh Anta Diop', 'Sénégalais', '''Nations nègres et culture'', Présence Africaine, 1954, p. 33', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_459fc103', 'Ma bouche sera la bouche des malheurs qui n''ont point de bouche.', 'Aimé Césaire', 'Martiniquais', '''Cahier d''un retour au pays natal'', Présence Africaine, 1939', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_9cabddb2', 'Les Noirs sont le seul peuple à qui on a demandé de prouver leur humanité.', 'James Baldwin', 'Américain', '''The Fire Next Time'', Dial Press, 1963, p. 91', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_e411a2fb', 'On ne nait pas avec une identité; on la construit.', 'Paul Ricoeur', 'Français', '''Soi-même comme un autre'', Seuil, 1990, p. 140', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_e01f792a', 'Ce que tu es parle si fort que je n''entends plus ce que tu dis.', 'Ralph Waldo Emerson', 'Américain', '''Letters and Social Aims'', 1876', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_3bd8fb41', 'Aucune culture ne peut vivre si elle tente d''être exclusive.', 'Mahatma Gandhi', 'Indien', '''Harijan'', 20 juillet 1935 — Collected Works of Mahatma Gandhi, Vol. 61', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_1ff456c3', 'L''histoire est un prophète qui regarde en arrière.', 'Eduardo Galeano', 'Uruguayen', '''Les Veines ouvertes de l''Amérique latine'', 1971', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_679b5a18', 'Ecrire dans sa langue est reprendre possession de soi-même.', 'Ngugi wa Thiong''o', 'Kenyan', '''Decolonising the Mind'', James Currey, 1986, p. 4', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_9c65c3cf', 'La colonisation du langage est la plus profonde des colonisations.', 'Ngugi wa Thiong''o', 'Kenyan', '''Decolonising the Mind'', James Currey, 1986, p. 9', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_03802d0a', 'Il est impossible de comprendre un peuple sans comprendre sa langue.', 'Nelson Mandela', 'Sud-Africain', 'Nelson Mandela Foundation — ''Nelson Mandela By Himself'', 2010', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_e53b2e26', 'La culture est la façon dont un peuple répond aux défis de son existence.', 'Aimé Césaire', 'Martiniquais', '''Discours sur la négritude'', Miami, 26 février 1987', 'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_747ac664', 'L''impérialisme a laissé dans nos mentalités des germes de la mort lente.', 'Frantz Fanon', 'Martiniquais', '''Les Damnés de la Terre'', Maspero, 1961, p. 311', 'verified', 'tp_identite_et_culture');
INSERT INTO topics (id, name) VALUES ('tp_existence_et_mort', 'Existence & Mort');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b08e002d', 'Il faut imaginer Sisyphe heureux.', 'Albert Camus', 'Français/Algérien', '''Le Mythe de Sisyphe'', Gallimard, 1942 — dernière phrase', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b9358ff1', 'L''existence précède l''essence.', 'Jean-Paul Sartre', 'Français', '''L''existentialisme est un humanisme'', Nagel, 1945', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_f52de8c1', 'Je pense, donc je suis.', 'René Descartes', 'Français', '''Discours de la méthode'', 1637, IVe partie ; aussi dans ''Méditations métaphysiques'', 1641', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_c0300c92', 'Les morts ne sont pas morts. Ils sont dans l''arbre qui frémit, dans le bois qui gémit.', 'Birago Diop', 'Sénégalais', '''Souffles'', in ''Leurres et Lueurs'', Présence Africaine, 1960', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_8de0750f', 'Je me suis fait une raison. Soit je finirai vieil homme quelque part, soit ce sera une fin violente.', 'Thomas Sankara', 'Burkinabé', 'Babelio — thomassankara.net | Scribd', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_c15ca324', 'La mort est quelque chose d''inévitable. Quand un homme a fait ce qu''il considère être son devoir, il peut reposer en paix.', 'Nelson Mandela', 'Sud-Africain', 'Documentaire ''Mandela'', 1994 — Nelson Mandela Foundation', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_f198a692', 'La mort ne nous concerne pas : quand nous existons, la mort n''est pas là ; quand elle est là, nous n''existons plus.', 'Épicure', 'Grec', '''Lettre à Ménécée'', ~300 av. J.-C.', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_2a607cc6', 'La vie est courte, l''art est long.', 'Hippocrate', 'Grec', '''Aphorismes'', §1, ~400 av. J.-C.', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_351597e5', 'L''homme n''est qu''un roseau, le plus faible de la nature ; mais c''est un roseau pensant.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 200, 1670 (posthume)', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_87d42494', 'Ce n''est pas parce que les choses sont difficiles que nous n''osons pas. C''est parce que nous n''osons pas qu''elles sont difficiles.', 'Sénèque', 'Romain', '''Lettres à Lucilius'', Lettre CIV', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_32ee0ea2', 'Le bonheur de ta vie dépend de la qualité de tes pensées.', 'Marc Aurèle', 'Romain', '''Pensées pour moi-même'' (Meditations), Livre III, §9 — traduction Gregory Hays', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_cf7b73b8', 'La philosophie est une méditation sur la mort.', 'Platon', 'Grec', '''Phédon'', 64a, ~380 av. J.-C.', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_bf508bc2', 'L''homme sage vit autant qu''il doit, non autant qu''il peut.', 'Michel de Montaigne', 'Français', '''Essais'', Livre I, Chapitre 20, 1580', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_d922b8f4', 'Je ne pense jamais au temps perdu. Je mets simplement en œuvre mon programme.', 'Nelson Mandela', 'Sud-Africain', 'Conversation avec Richard Stengel, 3 mai 1993 — Nelson Mandela Foundation', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_edb0098c', 'On ne sera plus là sera bientôt — cette pensée doit nous pousser à vivre pleinement.', 'Marc Aurèle', 'Romain', '''Pensées pour moi-même'', Livre II, §14 — traduction Gregory Hays', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_cef1a2b2', 'Le monde est ma représentation.', 'Arthur Schopenhauer', 'Allemand', '''Le Monde comme volonté et comme représentation'', Vol. I, §1, 1818', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_813a9b59', 'La vie oscille comme un pendule entre la douleur et l''ennui.', 'Arthur Schopenhauer', 'Allemand', '''Le Monde comme volonté et comme représentation'', Vol. I, §57, 1818', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_7cff84c7', 'Sur ce dont on ne peut parler, il faut garder le silence.', 'Ludwig Wittgenstein', 'Autrichien/Britannique', '''Tractatus Logico-Philosophicus'', Proposition 7, 1921', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b932bf64', 'La mort n''est pas un événement de la vie. La mort n''est pas vécue.', 'Ludwig Wittgenstein', 'Autrichien/Britannique', '''Tractatus Logico-Philosophicus'', Proposition 6.4311, 1921', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_d3c6dd91', 'J''ai rêvé que j''étais un papillon. À mon réveil je ne savais si j''étais un homme ayant rêvé être papillon, ou un papillon rêvant d''être un homme.', 'Zhuangzi', 'Chinois', '''Zhuangzi'', Chapitre II (''Sur l''égalité des choses''), ~300 av. J.-C.', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_62cfab91', 'L''enfer, c''est les autres.', 'Jean-Paul Sartre', 'Français', '''Huis clos'', Gallimard, 1944, Scène V', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_3333703f', 'Il n''y a qu''un problème philosophique vraiment sérieux : c''est le suicide.', 'Albert Camus', 'Français/Algérien', '''Le Mythe de Sisyphe'', Gallimard, 1942, p. 15', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_4f7b121f', 'Dieu est mort ! Dieu reste mort ! Et c''est nous qui l''avons tué !', 'Friedrich Nietzsche', 'Allemand', '''Le Gai Savoir'', §125, 1882', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_eb3d446f', 'Il faut du chaos en soi pour enfanter une étoile qui danse.', 'Friedrich Nietzsche', 'Allemand', '''Ainsi parlait Zarathoustra'', Prologue, §5, 1883', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_2b09c867', 'Ce que tu n''as pas en toi, tu ne peux pas le donner.', 'Amadou Hampâté Bâ', 'Malien', '''Amkoullel, l''enfant peul'', Actes Sud, 1991', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_c49bfa1b', 'Dum differtur vita transcurrit. Tandis que nous ajournons, la vie s''écoule.', 'Sénèque', 'Romain', '''Lettres à Lucilius'', Lettre I, ~65 ap. J.-C.', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_985b8dab', 'Ce que tu es maintenant est ce que tu feras de toi.', 'Jean-Paul Sartre', 'Français', '''L''existentialisme est un humanisme'', Nagel, 1945', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_fafc9e95', 'Mettez fin une fois pour toutes à cette discussion de ce que devrait être un homme bien. Soyez-le.', 'Marc Aurèle', 'Romain', '''Pensées pour moi-même'' (Meditations), Livre X, §16 — traduction Gregory Hays', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_3bb7284a', 'L''être précède le néant; le néant vient après.', 'Jean-Paul Sartre', 'Français', '''L''être et le néant'', Gallimard, 1943, Introduction', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_0bbd3053', 'L''existence précède l''essence, ce qui signifie que l''homme doit d''abord exister pour ensuite se définir.', 'Jean-Paul Sartre', 'Français', '''L''existentialisme est un humanisme'', Nagel, 1945', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_cd01dd8d', 'On n''est jamais aussi libre que quand on a admis qu''on allait mourir.', 'Albert Camus', 'Français/Algérien', '''L''Homme révolté'', Gallimard, 1951', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_2e55b893', 'La mort fait partie de la vie.', 'Ibn Khaldoun', 'Tunisien', '''Al-Muqaddimah'', Livre III, §15, 1377', 'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_7eb2d99f', 'Un seul être vous manque, et tout est dépeuplé.', 'Alphonse de Lamartine', 'Français', '''L''Isolement'', in ''Méditations poétiques'', 1820', 'verified', 'tp_existence_et_mort');
INSERT INTO topics (id, name) VALUES ('tp_femme_et_emancipation', 'Femme & Émancipation');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_be2c4dba', 'Il n''y a pas de révolution sociale véritable que lorsque la femme est libérée.', 'Thomas Sankara', 'Burkinabé', '''L''émancipation des femmes et la lutte de libération de l''Afrique'', Pathfinder Press, 2001, p. 45', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_d912178c', 'La source intarissable de toutes les victoires se trouve entre les mains de la femme.', 'Thomas Sankara', 'Burkinabé', '''La révolution ne peut aboutir sans l''émancipation des femmes'', 4 octobre 1984 — Wikiquote FR', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_4714e384', 'Nous ne parlons pas de l''émancipation des femmes comme d''un acte de charité. C''est une nécessité fondamentale pour le triomphe de la révolution.', 'Thomas Sankara', 'Burkinabé', 'nofi.media | thomassankara.net | Pathfinder Press, 2001', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_6191747f', 'L''inégalité ne peut être supprimée que par une nouvelle société où hommes et femmes jouiront de droits égaux.', 'Thomas Sankara', 'Burkinabé', 'Discours 8 mars 1987 — thomassankara.net | nofi.media', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_fa82ec56', 'Mères, sœurs, compagnes : il n''y a point d''homme fier tant qu''il n''y a point de femme à côté de lui.', 'Thomas Sankara', 'Burkinabé', '''La révolution ne peut aboutir sans l''émancipation des femmes'' — Wikiquote FR', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_761808d1', 'On ne naît pas femme, on le devient.', 'Simone de Beauvoir', 'Française', '''Le Deuxième Sexe'', Gallimard, 1949, Tome II, Chapitre 1', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_6809952f', 'Nous devrions tous être féministes.', 'Chimamanda Ngozi Adichie', 'Nigériane', 'TEDx Talk ''We Should All Be Feminists'', 2012 — publié en livre chez Vintage, 2014', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_6a06bf9d', 'Je ne suis pas libre si une sœur est enchaînée, même si ses chaînes sont très différentes des miennes.', 'Audre Lorde', 'Américaine', '''The Master''s Tools Will Never Dismantle the Master''s House'', 1984 — ''Sister Outsider'', Crossing Press', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_75ddd15c', 'La paix ne peut être atteinte sans la pleine et entière participation des femmes.', 'Leymah Gbowee', 'Libérienne', 'Discours — Prix Nobel de la Paix, Oslo, 10 décembre 2011', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_95466363', 'La femme est l''avenir de l''homme.', 'Louis Aragon', 'Français', '''Le Fou d''Elsa'', Gallimard, 1963', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_2f07b273', 'La femme n''est pas faite pour être la compagne de l''homme mais son égale.', 'John Stuart Mill', 'Britannique', '''L''Asservissement des femmes'', Chapitre I, 1869', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_88abc515', 'L''oppression des femmes est l''obstacle le plus fondamental à la liberté humaine.', 'John Stuart Mill', 'Britannique', '''L''Asservissement des femmes'', Chapitre I, 1869', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_39b35594', 'Aucune société ne peut s''émanciper sans l''émancipation des femmes.', 'Friedrich Engels', 'Allemand', '''L''Origine de la famille, de la propriété privée et de l''État'', Chapitre II, 1884', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b86725e9', 'On ne naît pas femme : on le devient. Aucun destin biologique ne définit la figure que revêt la femelle humaine au sein de la société.', 'Simone de Beauvoir', 'Française', '''Le Deuxième Sexe'', Tome II, Gallimard, 1949, p. 13', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_3b154470', 'Quand les femmes s''éveillent politiquement, elles sont les plus ardentes militantes.', 'Simone de Beauvoir', 'Française', '''Le Deuxième Sexe'', Tome I, Gallimard, 1949, p. 23', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_e940887f', 'Je mesure le courage d''une société au traitement qu''elle réserve à ses femmes.', 'Wole Soyinka', 'Nigérian', 'Discours Nobel de Littérature, Stockholm, 8 décembre 1986', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_5f5feeed', 'L''émancipation des femmes n''est pas une concession, c''est une révolution.', 'Aimé Césaire', 'Martiniquais', '''Discours sur la négritude'', Miami, 26 février 1987', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_085f844e', 'Pour nommer le monde à partir de sa propre expérience, la femme doit inventer un nouveau langage.', 'Hélène Cixous', 'Française/Algérienne', '''Le Rire de la Méduse'', L''Arc, n°61, 1975', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_98044562', 'La femme africaine a porté deux fois le poids de l''histoire : coloniale et patriarcale.', 'Frantz Fanon', 'Martiniquais', '''Les Damnés de la Terre'', Maspero, 1961, p. 218', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_e0bfb126', 'Chaque individu a le droit de disposer de sa propre personne.', 'John Locke', 'Britannique', '''Second traité du gouvernement civil'', §27, 1689', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_1d8a4775', 'Écrire, c''est pour la femme un acte révolutionnaire en soi.', 'Hélène Cixous', 'Française/Algérienne', '''Le Rire de la Méduse'', L''Arc, n°61, 1975', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_df920c00', 'L''éducation est accessible à tous sans distinction.', 'Confucius', 'Chinois', '''Entretiens'' (Analectes), Livre XV, §39, ~500 av. J.-C.', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_943d4290', 'La liberté des femmes est liée à la liberté de toute la société.', 'Simone de Beauvoir', 'Française', '''Le Deuxième Sexe'', Tome II, Gallimard, 1949, Conclusion', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_108c53b4', 'Une femme libre est précisément le contraire d''une femme facile.', 'Simone de Beauvoir', 'Française', '''La Force des choses'', Gallimard, 1963, p. 210', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_f6899946', 'Pour être libre, il ne faut pas être soumis.', 'Simone de Beauvoir', 'Française', '''Mémoires d''une jeune fille rangée'', Gallimard, 1958', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_78a981c2', 'L''oppression ne se limite pas à la loi; elle est dans les mentalités.', 'John Stuart Mill', 'Britannique', '''L''Asservissement des femmes'', Chapitre IV, 1869', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_e36d4253', 'Le véritable féminisme est la conviction que les femmes sont des êtres humains à part entière.', 'John Stuart Mill', 'Britannique', '''L''Asservissement des femmes'', Chapitre I, 1869', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_cd6d3ac9', 'Aucune femme ne naît soumise; elle le devient sous la contrainte sociale.', 'Friedrich Engels', 'Allemand', '''L''Origine de la famille, de la propriété privée et de l''État'', Chapitre IX, 1884', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_3f88d627', 'La question des droits des femmes n''est pas séparable de la question de la liberté humaine.', 'Harriet Taylor Mill', 'Britannique', '''L''Affranchissement des femmes'', Westminster Review, 1851', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_292d5397', 'Il y a deux grandes forces dans le monde : la peur et l''amour. La peur crée la domination, l''amour crée la liberté.', 'Hélène Cixous', 'Française/Algérienne', '''La Venue à l''écriture'', Union Générale d''Éditions, 1977', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_987c0855', 'La révolution ne peut être complète sans l''égalité des sexes.', 'August Bebel', 'Allemand', '''La Femme et le socialisme'', 1879', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_c9d61885', 'La vraie émancipation de la femme, c''est celle qui responsabilise la femme.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net | Dicocitations | Babelio', 'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b72d2891', 'Si la femme est libre, le monde est libre.', 'Victor Hugo', 'Français', '''Les Misérables'', Tome IV, Gallimard, 1862', 'verified', 'tp_femme_et_emancipation');
INSERT INTO topics (id, name) VALUES ('tp_nature_et_univers', 'Nature & Univers');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_74194ac5', 'Le cosmos est tout ce qui est, tout ce qui a été, tout ce qui sera.', 'Carl Sagan', 'Américain', '''Cosmos'', Random House, 1980, Chapitre 1 — première phrase du livre', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_a517d69d', 'Nous sommes tous faits de poussière d''étoiles.', 'Carl Sagan', 'Américain', '''Cosmos'', Random House, 1980', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_054bd604', 'La nature fait toujours les choses au mieux.', 'Aristote', 'Grec', '''De Partibus Animalium'', Livre I, ~350 av. J.-C.', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_90f82762', 'L''infini grand et l''infiniment petit se rejoignent dans l''immensité de l''univers.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 199 (Les deux infinis), 1670 (posthume)', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_2bbccb57', 'Un long voyage commence par un seul pas.', 'Lao Tzu', 'Chinois', '''Tao Te Ching'', Chapitre 64 — confirmé par Wikipedia, Taoism.net et multiple traductions académiques', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_141b3016', 'L''univers est non seulement plus étrange que nous le supposons, mais plus étrange que nous pouvons le supposer.', 'J.B.S. Haldane', 'Britannique', '''Possible Worlds and Other Papers'', Chatto & Windus, 1927', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_a7a711e4', 'Il faut cultiver notre jardin.', 'Voltaire', 'Français', '''Candide ou l''Optimisme'', 1759 — dernière réplique', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_0941dc02', 'Dieu, c''est-à-dire la Nature.', 'Baruch Spinoza', 'Néerlandais', '''Éthique'', Partie IV, Préface (''Deus, sive Natura''), 1677', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_bfefbf2b', 'Tout ce qui est, est en Dieu, et rien ne peut être ni être conçu sans Dieu.', 'Baruch Spinoza', 'Néerlandais', '''Éthique'', Partie I, Proposition XV, 1677', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_12dab86b', 'La durée réelle est ce que nous avons toujours appelé le temps, mais perçu comme indivisible.', 'Henri Bergson', 'Français', '''Essai sur les données immédiates de la conscience'', PUF, 1889, Chapitre II', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_1f3ab8c1', 'L''élan vital pousse la vie à se surpasser continuellement.', 'Henri Bergson', 'Français', '''L''Évolution créatrice'', PUF, 1907, Chapitre II', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_f758f93e', 'Chaque monade est un miroir vivant de l''univers.', 'Gottfried Wilhelm Leibniz', 'Allemand', '''Monadologie'', §56, 1714', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_21a8fad6', 'Le présent est chargé du passé et gros de l''avenir.', 'Gottfried Wilhelm Leibniz', 'Allemand', '''Nouveaux essais sur l''entendement humain'', Livre IV, Chapitre 16, §13, 1704', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_dd9f8ed4', 'Le silence éternel de ces espaces infinis m''effraie.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 206, 1670 (posthume)', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b2d31863', 'La vie et la mort sont une seule et même chose.', 'Zhuangzi', 'Chinois', '''Zhuangzi'', Chapitre VI (''Le grand ancêtre et maître''), ~300 av. J.-C.', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_819d34aa', 'L''univers est une totalité ordonnée dont chaque partie reflète le tout.', 'Ibn Sina (Avicenne)', 'Perse (Ouzbékistan)', '''Le Livre de la guérison'', Métaphysique, §8, ~1020', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_6288b585', 'L''univers est une machine à faire des dieux.', 'Henri Bergson', 'Français', '''Les Deux Sources de la morale et de la religion'', PUF, 1932, Conclusion', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_d2bd1001', 'L''Afrique est le continent où l''humanité a effectué ses premiers pas.', 'Cheikh Anta Diop', 'Sénégalais', '''L''Unité culturelle de l''Afrique noire'', Présence Africaine, 1959, p. 9', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_66293b8b', 'La matière est habitude prise ; l''esprit est habitude contractée.', 'Henri Bergson', 'Français', '''Matière et mémoire'', PUF, 1896, Conclusion', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_588c7f95', 'Le Tao qui peut être nommé n''est pas le Tao éternel.', 'Lao Tzu', 'Chinois', '''Tao Te Ching'', Chapitre 1, ~VIe siècle av. J.-C.', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_e74df812', 'La nature est partout; il n''y a pas de vide dans l''univers.', 'Gottfried Wilhelm Leibniz', 'Allemand', '''Monadologie'', §3, 1714', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_32c3209f', 'Le plus grand miracle du monde, c''est le monde lui-même.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 267, 1670 (posthume)', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_5e15b049', 'La nature n''a ni noyau ni écorce : elle est tout à la fois.', 'Johann Wolfgang von Goethe', 'Allemand', '''Maximes et réflexions'', §575, 1833 (posthume)', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_60123880', 'La nature est un temple où de vivants piliers laissent parfois sortir de confuses paroles.', 'Charles Baudelaire', 'Français', '''Correspondances'', in ''Les Fleurs du mal'', 1857', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_5a5867ad', 'L''histoire naturelle du monde est l''histoire de la lutte pour l''existence.', 'Charles Darwin', 'Britannique', '''De l''origine des espèces'', John Murray, 1859, Chapitre III', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_fdf62553', 'Dans les forêts, il y a quelque chose de mystérieusement vivant.', 'Jean-Jacques Rousseau', 'Suisse/Français', '''Les Rêveries du promeneur solitaire'', Cinquième promenade, 1782', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_be1217e1', 'L''infiniment grand me dépasse ; l''infiniment petit me contient.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 199, 1670 (posthume)', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_02289ecb', 'Nous sommes de la même substance que les songes.', 'William Shakespeare', 'Britannique', '''La Tempête'', Acte IV, Scène I, 1611', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_e82d53c0', 'Le monde est beau parce qu''il périt.', 'Albert Camus', 'Français/Algérien', '''Noces'', Gallimard, 1938', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_dbc868ab', 'La Terre tourne, et les empires s''effondrent, mais la nature reste.', 'Leonardo da Vinci', 'Italien', 'Carnets, ~1495 — Bibliothèque Ambrosienne, Milan', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_9ea3858e', 'Tout est eau.', 'Thalès de Milet', 'Grec', 'Rapporté par Aristote, ''Métaphysique'', Livre I, §3 (983b6), ~335 av. J.-C.', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_08f2c83b', 'Tout est flux et rien ne reste fixe.', 'Héraclite', 'Grec', 'Fragment DK22B91 — rapporté par Platon dans ''Cratyle'', 402a', 'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_635ad9eb', 'La nature, pour être commandée, doit être obéie.', 'Francis Bacon', 'Britannique', '''Novum Organum'', §3, 1620', 'verified', 'tp_nature_et_univers');
INSERT INTO topics (id, name) VALUES ('tp_amour_et_relations', 'Amour & Relations');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_6cbafa08', 'Aimer, ce n''est pas se regarder l''un l''autre, c''est regarder ensemble dans la même direction.', 'Antoine de Saint-Exupéry', 'Français', '''Terre des hommes'', Gallimard, 1939, Chapitre 8', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_dc5013c2', 'Le cœur a ses raisons que la raison ne connaît point.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 277, 1670 (posthume)', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_942955cf', 'L''amitié véritable est l''autre soi-même.', 'Cicéron', 'Romain', '''Laelius de Amicitia'', §21, ~44 av. J.-C.', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b7c7ed62', 'Ce n''est pas le manque d''amour mais le manque d''amitié qui rend les mariages malheureux.', 'Friedrich Nietzsche', 'Allemand', '''Humain, trop humain'', §393, 1878', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_0a4087fe', 'L''amitié double les joies et divise les douleurs.', 'Francis Bacon', 'Britannique', '''Essays'', ''Of Friendship'', §27, 1625', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_c9296e02', 'Un seul être vous manque, et tout est dépeuplé.', 'Alphonse de Lamartine', 'Français', '''L''Isolement'', in ''Méditations poétiques'', 1820', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_26a7ef93', 'A un interlocuteur qui me demandait ce que l''Afrique pourrait apporter, j''ai répondu : ''le rire, que vous avez perdu.''', 'Amadou Hampâté Bâ', 'Malien', '''Aspects de la civilisation africaine'', Présence Africaine, 1972, p. 21-22', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_26046698', 'La bienveillance universelle (ren) est le fondement de toute vertu.', 'Confucius', 'Chinois', '''Entretiens'' (Analectes), Livre XII, §1, ~500 av. J.-C.', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_0d461d4e', 'L''amour est un désir de procréer et d''engendrer dans la beauté.', 'Platon', 'Grec', '''Le Banquet'', 206e, ~380 av. J.-C.', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_eb1f1fa5', 'Ce que j''appelle l''amour véritable, c''est l''amour de l''âme pour l''âme.', 'Platon', 'Grec', '''Phèdre'', 256e, ~370 av. J.-C.', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_c7c4c952', 'Votre douleur est la dissolution de la coquille qui enferme votre compréhension.', 'Khalil Gibran', 'Libanais', '''Le Prophète'', Alfred A. Knopf, 1923, ''De la douleur''', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_573410f1', 'Vos enfants ne sont pas vos enfants. Ils sont les fils et les filles de l''appel de la Vie à elle-même.', 'Khalil Gibran', 'Libanais', '''Le Prophète'', Alfred A. Knopf, 1923, ''Des enfants''', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_cb30ced8', 'Le travail est l''amour rendu visible.', 'Khalil Gibran', 'Libanais', '''Le Prophète'', Alfred A. Knopf, 1923, ''Du travail''', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_8ae71a1a', 'On ne voit bien qu''avec le cœur ; l''essentiel est invisible pour les yeux.', 'Antoine de Saint-Exupéry', 'Français', '''Le Petit Prince'', Gallimard, 1943, Chapitre XXI', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_e97ecc91', 'Tu deviens responsable pour toujours de ce que tu as apprivoisé.', 'Antoine de Saint-Exupéry', 'Français', '''Le Petit Prince'', Gallimard, 1943, Chapitre XXI', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_7c8be304', 'Bonheur ou malheur dépendent entièrement de la qualité de l''objet que nous aimons.', 'Baruch Spinoza', 'Néerlandais', '''Traité de la réforme de l''entendement'', §9, 1677', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_50f5b5e2', 'L''homme de bien cherche en lui-même ce qu''il veut trouver. L''homme ordinaire le cherche chez les autres.', 'Confucius', 'Chinois', '''Entretiens'' (Analectes), Livre XV, §21, ~500 av. J.-C.', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_fffcea40', 'Toute l''infortune des hommes vient d''une seule chose : ne savoir pas demeurer en repos dans une chambre.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 139, 1670 (posthume)', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_39ac4f03', 'Parce que c''était lui, parce que c''était moi.', 'Michel de Montaigne', 'Français', '''Essais'', Livre I, Chapitre 28, 1580 — sur son amitié avec La Boétie', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_3bc6a2d8', 'Ita fac, mi Lucili: vindica te tibi. Reprends possession de toi-même.', 'Sénèque', 'Romain', '''Lettres à Lucilius'', Lettre I, ~65 ap. J.-C.', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_c0f68a77', 'La douleur de l''amour est préférable à la mort de l''indifférence.', 'Rumi', 'Perse (Afghanistan)', '''Masnavi'', Livre I, vers 110, XIIIe siècle', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_ff16f093', 'L''amour est la connaissance active de la personne aimée.', 'Erich Fromm', 'Allemand/Américain', '''L''Art d''aimer'', HarperCollins, 1956, p. 26', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_74fa74d1', 'La maturité de l''amour est la capacité d''aimer l''autre tel qu''il est.', 'Erich Fromm', 'Allemand/Américain', '''L''Art d''aimer'', HarperCollins, 1956, p. 23', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_70f973dd', 'Aimer, c''est accepter de ne pas comprendre l''autre entièrement.', 'Gabriel Marcel', 'Français', '''Être et Avoir'', Aubier-Montaigne, 1935', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_5b959e96', 'On ne peut être véritablement ami que de quelqu''un de meilleur que soi.', 'Aristote', 'Grec', '''Éthique à Nicomaque'', Livre VIII, Chapitre 3 (1156b), ~335 av. J.-C.', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_3a1aeb62', 'Le mariage est le meilleur et le pire des choses.', 'Aristote', 'Grec', 'Rapporté par Diogène Laërce, ''Vies des philosophes'', Livre V, §19', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_35078674', 'Ce qui est fait par amour est toujours au-delà du bien et du mal.', 'Friedrich Nietzsche', 'Allemand', '''Par-delà bien et mal'', §153, 1886', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_53220361', 'L''amour est aveugle, l''amitié ferme les yeux.', 'Friedrich Nietzsche', 'Allemand', '''Humain, trop humain'', Vol. II, §394, 1879', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_2469187e', 'Les liens les plus forts ne sont pas ceux que l''on choisit mais ceux que la vie impose.', 'Albert Camus', 'Français/Algérien', '''L''Étranger'', Gallimard, 1942', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_6309618e', 'L''amour s''apprend comme se lit un livre, lentement.', 'Rumi', 'Perse (Afghanistan)', '''Masnavi'', Livre II, vers 1, XIIIe siècle', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_b492003c', 'Connaître autrui est savoir, se connaître soi-même est savoir avec sagesse.', 'Lao Tzu', 'Chinois', '''Tao Te Ching'', Chapitre 33, ~VIe siècle av. J.-C.', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_4bcca1dc', 'L''amour véritable est permanent, sans conditions ni récompenses attendues.', 'Erich Fromm', 'Allemand/Américain', '''L''Art d''aimer'', HarperCollins, 1956, p. 38', 'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, statut, topic_id) VALUES ('qt_db52d7b7', 'La dignité humaine n''est pas un privilège; elle se construit dans la relation à l''autre.', 'Paul Ricoeur', 'Français', '''Soi-même comme un autre'', Seuil, 1990, p. 202', 'verified', 'tp_amour_et_relations');
